class Solution {
public:
    int maxTotalReward(vector<int>& rewardValues) {
        sort(rewardValues.begin(), rewardValues.end());
        rewardValues.erase(unique(rewardValues.begin(), rewardValues.end()), rewardValues.end());
        bitset<100000> dp;
        dp[0] = 1;
        for (int v : rewardValues) {
            bitset<100000> mask;
            int shift = 100000 - v;
            mask.set();
            mask >>= shift;
            dp |= (dp & mask) << v;
        }
        for (int i = 99999; i >= 0; --i) {
            if (dp[i]) return i;
        }
        return 0;
    }
};

import java.math.BigInteger;

class Solution {
    public int maxTotalReward(int[] rewardValues) {
        Arrays.sort(rewardValues);
        BigInteger dp = BigInteger.ONE;
        int prev = -1;
        for (int v : rewardValues) {
            if (v == prev) continue;
            prev = v;
            BigInteger mask = BigInteger.ONE.shiftLeft(v).subtract(BigInteger.ONE);
            BigInteger valid = dp.and(mask);
            dp = dp.or(valid.shiftLeft(v));
        }
        return dp.bitLength() - 1;
    }
}

var maxTotalReward = function(rewardValues) {
    rewardValues = Array.from(new Set(rewardValues)).sort((a, b) => a - b);
    let dp = 1n;
    for (const v of rewardValues) {
        const mask = (1n << BigInt(v)) - 1n;
        const valid = dp & mask;
        dp |= (valid << BigInt(v));
    }
    return dp.toString(2).length - 1;
};
